const source = $('Execute Workflow Trigger').item.json || {};
const args = source.args || source.payload?.args || {};
const payload = source.payload || {};
const message = source.message || payload.message || payload.body?.message || {};
const chatId = source.chatId || message.chat?.id || payload.chatId || '';

const raw = String(source.rawText || source.text || source.fileName || args.fileName || message.text || payload.text || '').trim();

function normalize(str) {
  return String(str || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/g, 'd')
    .replace(/Đ/g, 'D')
    .trim();
}

function cleanName(value) {
  return String(value || '')
    .trim()
    .replace(/^[\"'“”‘’]+|[\"'“”‘’]+$/g, '')
    .replace(/\s+/g, ' ');
}

function parseExportCommand(rawText) {
  const original = String(rawText || '').trim();
  const normalized = normalize(original);

  const prefixes = ['xuat file', 'export file', 'chuyen file', 'tai file', 'download file', 'gui toi file', 'gui file'];
  let bodyOriginal = original;
  let bodyNormalized = normalized;

  for (const prefix of prefixes) {
    if (normalized.startsWith(prefix + ' ')) {
      bodyOriginal = original.slice(prefix.length + 1).trim();
      bodyNormalized = normalized.slice(prefix.length + 1).trim();
      break;
    }
    if (normalized === prefix) return { fileName: '', format: '' };
  }

  const separators = [' sang ', ' thanh ', ' dang ', ' dinh dang ', ' format ', ' as ', ' to '];

  for (const sep of separators) {
    const index = bodyNormalized.lastIndexOf(sep);
    if (index !== -1) {
      return {
        fileName: cleanName(bodyOriginal.slice(0, index)),
        format: cleanName(bodyOriginal.slice(index + sep.length)).replace(/^\./, '').toLowerCase()
      };
    }
  }

  return { fileName: cleanName(bodyOriginal), format: '' };
}

function extensionOf(name) {
  const m = String(name || '').match(/\.([a-z0-9]{1,12})$/i);
  return m ? m[1].toLowerCase() : '';
}

const parsed = parseExportCommand(raw);

const fileId = source.fileId || source.targetId || args.fileId || args.targetId || payload.fileId || payload.targetId || '';
const fileName = cleanName(source.fileName || source.targetName || args.fileName || args.targetName || payload.fileName || payload.targetName || parsed.fileName);
const requestedFormat = cleanName(source.format || source.mimeType || args.format || args.mimeType || payload.format || parsed.format || '').toLowerCase().replace(/^\./, '');
const inferredFormat = requestedFormat || extensionOf(fileName) || 'pdf';
const hasTarget = Boolean(fileId || fileName);

return [{
  json: {
    ...source, payload, message, chatId, raw, rawText: raw, text: normalize(raw),
    fileId, targetId: fileId, fileName, targetName: fileName,
    format: inferredFormat, requestedFormat, hasTarget,
    response: hasTarget ? '' : '📤 <b>Xuất / tải file</b>\n\nVí dụ:\n<code>xuất file báo cáo sang pdf</code>\n<code>export file report sang docx</code>\n<code>tải file note.md</code>'
  }
}];

const source = $('Prepare Action').item.json || {};
function escapeHtml(value = '') {
  return String(value).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}
const rows = $input.all().map((item) => item.json || {}).filter((item) => item.id || item.name);
if (!rows.length) {
  return [{ json: { ...source, found: false, fileId: '', targetId: '', response: 'Không tìm thấy file phù hợp với: <b>' + escapeHtml(source.fileName || source.targetName || '') + '</b>' } }];
}
const file = rows[0];
return [{
  json: {
    ...source, ...file, found: true,
    fileId: file.id || source.fileId || '',
    targetId: file.id || source.targetId || source.fileId || '',
    fileName: file.name || source.fileName || source.targetName || '',
    targetName: file.name || source.targetName || source.fileName || '',
    webViewLink: file.webViewLink || source.webViewLink || '',
    webContentLink: file.webContentLink || source.webContentLink || '',
    mimeType: file.mimeType || source.mimeType || '',
    format: source.format || '',
    requestedFormat: source.requestedFormat || ''
  }
}];

const prepared = $('Prepare Action').item.json || {};
const meta = $input.item.json || {};

function cleanExt(value) { return String(value || '').toLowerCase().replace(/^\./, '').trim(); }
function extOf(name) { const m = String(name || '').match(/\.([a-z0-9]{1,12})$/i); return m ? m[1].toLowerCase() : ''; }
function baseName(name) { return String(name || 'file').replace(/\.[^/.]+$/, ''); }

function mimeForBlobExt(ext) {
  const map = {
    txt:'text/plain', md:'text/markdown', markdown:'text/markdown', json:'application/json', jsonl:'application/x-ndjson',
    csv:'text/csv', tsv:'text/tab-separated-values', html:'text/html', htm:'text/html', xml:'application/xml',
    yaml:'application/x-yaml', yml:'application/x-yaml', toml:'application/toml', js:'application/javascript',
    mjs:'application/javascript', ts:'application/typescript', css:'text/css', py:'text/x-python', sql:'application/sql',
    svg:'image/svg+xml', pdf:'application/pdf', doc:'application/msword',
    docx:'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
    xls:'application/vnd.ms-excel', xlsx:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
    ppt:'application/vnd.ms-powerpoint', pptx:'application/vnd.openxmlformats-officedocument.presentationml.presentation',
    png:'image/png', jpg:'image/jpeg', jpeg:'image/jpeg', gif:'image/gif', webp:'image/webp',
    zip:'application/zip', rar:'application/vnd.rar', '7z':'application/x-7z-compressed'
  };
  return map[ext] || 'application/octet-stream';
}

const exportFormats = {
  'application/vnd.google-apps.document': {
    pdf:{mime:'application/pdf',ext:'pdf'}, docx:{mime:'application/vnd.openxmlformats-officedocument.wordprocessingml.document',ext:'docx'},
    odt:{mime:'application/vnd.oasis.opendocument.text',ext:'odt'}, rtf:{mime:'application/rtf',ext:'rtf'},
    txt:{mime:'text/plain',ext:'txt'}, zip:{mime:'application/zip',ext:'zip'}, html:{mime:'application/zip',ext:'zip'},
    epub:{mime:'application/epub+zip',ext:'epub'}, md:{mime:'text/markdown',ext:'md'}
  },
  'application/vnd.google-apps.spreadsheet': {
    xlsx:{mime:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',ext:'xlsx'},
    ods:{mime:'application/x-vnd.oasis.opendocument.spreadsheet',ext:'ods'}, pdf:{mime:'application/pdf',ext:'pdf'},
    zip:{mime:'application/zip',ext:'zip'}, html:{mime:'application/zip',ext:'zip'}, csv:{mime:'text/csv',ext:'csv'},
    tsv:{mime:'text/tab-separated-values',ext:'tsv'}
  },
  'application/vnd.google-apps.presentation': {
    pptx:{mime:'application/vnd.openxmlformats-officedocument.presentationml.presentation',ext:'pptx'},
    odp:{mime:'application/vnd.oasis.opendocument.presentation',ext:'odp'}, pdf:{mime:'application/pdf',ext:'pdf'},
    txt:{mime:'text/plain',ext:'txt'}, jpg:{mime:'image/jpeg',ext:'jpg'}, jpeg:{mime:'image/jpeg',ext:'jpg'},
    png:{mime:'image/png',ext:'png'}, svg:{mime:'image/svg+xml',ext:'svg'}
  },
  'application/vnd.google-apps.drawing': {
    pdf:{mime:'application/pdf',ext:'pdf'}, jpg:{mime:'image/jpeg',ext:'jpg'}, jpeg:{mime:'image/jpeg',ext:'jpg'},
    png:{mime:'image/png',ext:'png'}, svg:{mime:'image/svg+xml',ext:'svg'}
  },
  'application/vnd.google-apps.script': {
    json:{mime:'application/vnd.google-apps.script+json',ext:'json'}
  }
};

const fileId = meta.id || meta.fileId || prepared.fileId || prepared.targetId || '';
const fileName = meta.name || prepared.fileName || prepared.targetName || 'file';
const sourceMimeType = meta.mimeType || prepared.mimeType || '';
let requestedFormat = cleanExt(prepared.format || prepared.requestedFormat || '');
const sourceExt = extOf(fileName);
const isWorkspace = sourceMimeType.startsWith('application/vnd.google-apps.');

let canSend = false, mode = '', contentUrl = '', outputExt = '', outputMimeType = '', outputFileName = '', warning = '', errorMessage = '';

if (!fileId) {
  errorMessage = 'Không có File ID để export/download.';
} else if (isWorkspace) {
  const allowed = exportFormats[sourceMimeType] || {};
  if (!requestedFormat) {
    if (sourceMimeType === 'application/vnd.google-apps.document') requestedFormat = 'pdf';
    else if (sourceMimeType === 'application/vnd.google-apps.spreadsheet') requestedFormat = 'xlsx';
    else if (sourceMimeType === 'application/vnd.google-apps.presentation') requestedFormat = 'pptx';
    else if (sourceMimeType === 'application/vnd.google-apps.drawing') requestedFormat = 'png';
    else if (sourceMimeType === 'application/vnd.google-apps.script') requestedFormat = 'json';
    else requestedFormat = 'pdf';
  }

  const target = allowed[requestedFormat];
  if (!target) {
    errorMessage = `File Google Workspace loại này không hỗ trợ export sang .${requestedFormat}. Các định dạng hỗ trợ: ${Object.keys(allowed).map((x) => '.' + x).join(', ') || 'không rõ'}.`;
  } else {
    mode = 'export';
    outputExt = target.ext;
    outputMimeType = target.mime;
    outputFileName = `${baseName(fileName)}.${outputExt}`;
    contentUrl = `https://www.googleapis.com/drive/v3/files/${encodeURIComponent(fileId)}/export?mimeType=${encodeURIComponent(outputMimeType)}`;
    canSend = true;
  }
} else {
  mode = 'download';
  outputExt = sourceExt || requestedFormat || 'bin';
  outputMimeType = sourceMimeType || mimeForBlobExt(outputExt);
  outputFileName = fileName.includes('.') ? fileName : `${fileName}.${outputExt}`;
  contentUrl = `https://www.googleapis.com/drive/v3/files/${encodeURIComponent(fileId)}?alt=media`;
  canSend = true;

  if (requestedFormat && sourceExt && requestedFormat !== sourceExt) {
    warning = `File thường không convert bằng export endpoint. Mình sẽ gửi file gốc .${sourceExt}, không chuyển sang .${requestedFormat}.`;
  }
}

return [{
  json: {
    ...prepared, ...meta, fileId, targetId: fileId, fileName,
    sourceMimeType, mimeType: sourceMimeType, requestedFormat, mode,
    canSend, contentUrl, outputExt, outputMimeType, outputFileName, warning, errorMessage
  }
}];

const meta = $('Prepare Export Request').item.json || {};
const bin = $input.item.binary || {};

function esc(value = '') {
  return String(value).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

return [{
  json: {
    chatId: meta.chatId,
    caption: [
      meta.mode === 'export' ? '📤 <b>Đã export file</b>' : '📥 <b>Đã tải file gốc</b>',
      '',
      `📄 <b>${esc(meta.outputFileName || meta.fileName || 'file')}</b>`,
      meta.outputMimeType ? `Loại: <code>${esc(meta.outputMimeType)}</code>` : '',
      meta.warning ? `\n⚠️ ${esc(meta.warning)}` : ''
    ].filter(Boolean).join('\n'),
    fileName: meta.outputFileName || meta.fileName || 'file',
    mimeType: meta.outputMimeType || meta.mimeType || 'application/octet-stream'
  },
  binary: {
    data: {
      ...(bin.data || {}),
      fileName: meta.outputFileName || meta.fileName || bin.data?.fileName || 'file',
      mimeType: meta.outputMimeType || meta.mimeType || bin.data?.mimeType || 'application/octet-stream'
    }
  }
}];

const escapeHtml = (value = '') => String(value)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const item = $input.item.json || {};
let text = '⚠️ <b>Không thể export/download file</b>\n\n';
if (item.fileName) text += `📄 <b>${escapeHtml(item.fileName)}</b>\n`;
if (item.mimeType) text += `MIME: <code>${escapeHtml(item.mimeType)}</code>\n`;
if (item.requestedFormat) text += `Định dạng yêu cầu: <code>.${escapeHtml(item.requestedFormat)}</code>\n`;
text += '\n' + escapeHtml(item.errorMessage || 'Không xác định được cách export/download file này.');
if (item.webViewLink) text += `\n🔗 <a href="${escapeHtml(item.webViewLink)}">Mở file gốc</a>`;
return [{ json: { chatId: item.chatId, text: text.trim() } }];

const source = $json || {};

function decodeEntities(value = '') {
  return String(value)
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'");
}

function htmlToPlainText(value = '') {
  return decodeEntities(String(value || ''))
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n\n')
    .replace(/<\/div>/gi, '\n')
    .replace(/<\/li>/gi, '\n')
    .replace(/<li>/gi, '- ')
    .replace(/<\/h\d>/gi, '\n')
    .replace(/<a[^>]*href="([^"]+)"[^>]*>(.*?)<\/a>/gi, '$2: $1')
    .replace(/<[^>]+>/g, ' ')
    .replace(/[ \t]+/g, ' ')
    .replace(/\s+([,.;:!?])/g, '$1')
    .replace(/\n\s+/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

const target =
  source.query ||
  source.docName ||
  source.sheetName ||
  source.fileName ||
  source.folderName ||
  source.targetName ||
  source.title ||
  source.summary ||
  source.rawText ||
  source.text ||
  '';

let text = htmlToPlainText(source.response || source.text || source.error || '');
if (!text) {
  text = target
    ? `Mia chưa xử lý được yêu cầu với "${target}". Bạn kiểm tra lại thông tin đầu vào giúp Mia nhé.`
    : 'Mia chưa đủ thông tin để xử lý yêu cầu này.';
}

return [{
  json: {
    ok: false,
    tool: source.tool || source.workflowKey || '',
    chatId: source.chatId || '',
    text,
    links: [],
    result: {},
    meta: {
      target: String(target || '').trim(),
      reason: source.hasTarget === false || source.isReady === false ? 'missing_required_input' : 'not_found_or_not_applicable'
    }
  }
}];
